{"implementation":"def solve(case):
    threshold = case["threshold"]
    calls = case["calls"]
    accepted = []
    diagnostics = []
    for call in calls:
        call_id = call["call_id"]
        gain = call["loss_without_call"] - call["loss_with_call"]
        norm_gain = gain / call["prediction_tokens"]
        is_parseable = call["parseable"]
        accept = is_parseable and norm_gain >= threshold
        if accept:
            accepted.append(call_id)
        diagnostics.append({
            "accepted": accept,
            "call_id": call_id,
            "normalized_gain": norm_gain
        })
    return {
        "accepted_call_ids": accepted,
        "diagnostics": diagnostics
    }"}
